package com.shock.stream;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.graphics.*;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.os.*;import android.util.DisplayMetrics;import java.io.*;import java.net.*;import java.util.concurrent.atomic.AtomicReference;
public class CaptureService extends Service {
 private MediaProjection projection;private VirtualDisplay display;private ImageReader reader;private ServerSocket socket;private Thread serverThread;private volatile boolean running;private final AtomicReference<byte[]> frame=new AtomicReference<>();
 @Override public void onCreate(){super.onCreate();NotificationChannel channel=new NotificationChannel("capture","Captura de tela",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(channel);Notification n=new Notification.Builder(this,"capture").setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("Shock Android Stream").setContentText("Compartilhando tela na rede local").build();startForeground(1,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);}
 @Override public int onStartCommand(Intent i,int flags,int id){if(running)return START_NOT_STICKY;if(i==null)return START_NOT_STICKY;Intent data=i.getParcelableExtra("data");if(data==null)return START_NOT_STICKY;try{MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);projection=m.getMediaProjection(i.getIntExtra("result",0),data);projection.registerCallback(new MediaProjection.Callback(){@Override public void onStop(){stopSelf();}},new Handler(Looper.getMainLooper()));DisplayMetrics dm=getResources().getDisplayMetrics();int w=640,h=Math.max(2,((int)(640.0*dm.heightPixels/dm.widthPixels)/2)*2);reader=ImageReader.newInstance(w,h,PixelFormat.RGBA_8888,2);HandlerThread ht=new HandlerThread("capture");ht.start();reader.setOnImageAvailableListener(ir->{Image im=ir.acquireLatestImage();if(im==null)return;try{Image.Plane p=im.getPlanes()[0];int stride=p.getRowStride(),pix=p.getPixelStride();Bitmap raw=Bitmap.createBitmap(w+(stride-pix*w)/pix,h,Bitmap.Config.ARGB_8888);raw.copyPixelsFromBuffer(p.getBuffer());Bitmap cropped=Bitmap.createBitmap(raw,0,0,w,h);ByteArrayOutputStream out=new ByteArrayOutputStream();cropped.compress(Bitmap.CompressFormat.JPEG,55,out);frame.set(out.toByteArray());cropped.recycle();raw.recycle();}catch(Exception ignored){}finally{im.close();}},new Handler(ht.getLooper()));display=projection.createVirtualDisplay("ShockStream",w,h,dm.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,reader.getSurface(),null,null);running=true;serverThread=new Thread(this::serve);serverThread.start();}catch(Exception e){stopSelf();}return START_NOT_STICKY;}
 private void serve(){try(ServerSocket s=new ServerSocket(8088)){socket=s;while(running){Socket client=s.accept();new Thread(()->handle(client)).start();}}catch(Exception ignored){}}
 private void handle(Socket c){try(Socket client=c){client.setSoTimeout(10000);BufferedReader input=new BufferedReader(new InputStreamReader(client.getInputStream()));String request=input.readLine();if(request==null)return;while(true){String line=input.readLine();if(line==null||line.isEmpty())break;}OutputStream o=client.getOutputStream();if(request.startsWith("GET /video")){o.write(("HTTP/1.1 200 OK\r\nContent-Type: multipart/x-mixed-replace; boundary=frame\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n").getBytes("UTF-8"));while(running){byte[] b=frame.get();if(b!=null){o.write(("--frame\r\nContent-Type: image/jpeg\r\nContent-Length: "+b.length+"\r\n\r\n").getBytes("UTF-8"));o.write(b);o.write("\r\n".getBytes("UTF-8"));o.flush();}Thread.sleep(200);}}else{byte[] body=("<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1,user-scalable=no'><style>body{margin:0;background:#101319;color:white;font-family:Arial;text-align:center}img{width:100%;height:auto}h3{font-weight:normal}</style></head><body><h3>Shock Android Stream v0.1</h3><img src='/video' alt='Captura Android'><p>Visualização MJPEG experimental. Controles e áudio ainda não implementados.</p></body></html>").getBytes("UTF-8");o.write(("HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes("UTF-8"));o.write(body);o.flush();}}catch(Exception ignored){}}
 @Override public void onDestroy(){running=false;try{if(socket!=null)socket.close();}catch(Exception ignored){}if(display!=null)display.release();if(reader!=null)reader.close();if(projection!=null)projection.stop();super.onDestroy();}
 @Override public android.os.IBinder onBind(Intent i){return null;}
}